import csv
import io
import re
from typing import List, Dict, Any


def _is_data_leading(value: str) -> bool:
    value = value.strip()
    return bool(
        re.match(r"^\d{1,4}[-/]\d{1,2}[-/]\d{1,4}", value)
        or re.match(r"^\d+(?:\.\d+)?$", value)
    )


def _header_score(row: List[str]) -> int:
    score = 0
    for value in row:
        text = value.strip()
        if text:
            if re.search(r"[A-Za-z]", text):
                score += 1
            if re.search(r"(date|time|id|qty|quantity|price|url|description|comment|name|type)", text, re.I):
                score += 3
    return score


def _find_header(records: List[List[str]], expected_width: int) -> int:
    best_index = -1
    best_score = -1

    for index, row in enumerate(records):
        if not row:
            continue
        score = _header_score(row)
        if index + 1 < len(records):
            following = records[index + 1]
            if following and _is_data_leading(following[0]):
                score += 8
        if len(row) == expected_width:
            score += 2
        if score > best_score and (len(row) >= 2 or expected_width == 1):
            best_index = index
            best_score = score

    if best_index >= 0:
        return best_index

    for index, row in enumerate(records):
        if len(row) >= expected_width:
            return index

    return 0 if records else -1


def _normalize_header(row: List[str], width: int) -> List[str]:
    values = list(row)
    if len(values) < width:
        values.extend([""] * (width - len(values)))
    elif len(values) > width:
        values = values[:width - 1] + [",".join(values[width - 1:])]
    return values


def _find_special_columns(header: List[str]) -> Dict[str, int]:
    result: Dict[str, int] = {}
    for index, value in enumerate(header):
        name = value.strip().lower()
        if "url" in name or "link" in name or "website" in name:
            result.setdefault("url", index)
        if any(word in name for word in ("description", "detail", "product name", "item name")):
            result.setdefault("description", index)
        if "comment" in name or "note" in name:
            result.setdefault("comment", index)
    return result


def _normalize_row(row: List[str], width: int, header: List[str]) -> List[str]:
    values = list(row)

    if len(values) < width:
        values.extend([""] * (width - len(values)))
        return values

    if len(values) == width:
        return values

    columns = _find_special_columns(header)
    url_index = columns.get("url")

    if url_index is not None:
        url_position = None
        for index, value in enumerate(values):
            if re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", value.strip()):
                url_position = index
                break

        if url_position is not None and url_position > url_index:
            merge_index = columns.get("description", url_index - 1)
            merge_index = max(0, min(merge_index, width - 1))
            excess_before_url = url_position - url_index
            end = min(len(values), merge_index + excess_before_url + 1)
            values = (
                values[:merge_index]
                + [",".join(values[merge_index:end])]
                + values[end:]
            )

    if len(values) > width:
        merge_index = columns.get(
            "description",
            columns.get("comment", width - 1)
        )
        merge_index = max(0, min(merge_index, len(values) - 1))
        excess = len(values) - width
        end = min(len(values), merge_index + excess + 1)
        values = values[:merge_index] + [",".join(values[merge_index:end])] + values[end:]

    if len(values) > width:
        values = values[:width - 1] + [",".join(values[width - 1:])]
    elif len(values) < width:
        values.extend([""] * (width - len(values)))

    return values


def _looks_like_footer(row: List[str]) -> bool:
    if len(row) != 1:
        return False
    value = row[0].strip()
    return bool(re.match(
        r"^(?:foot(?:er)?|end(?:\s+of\s+file)?|the\s+end|notes?|source|generated|totals?)$",
        value,
        re.I
    ))


def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""

    stream = io.StringIO(raw_csv, newline="")
    reader = csv.reader(
        stream,
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False
    )

    records: List[List[str]] = []
    try:
        for row in reader:
            if row and any(cell != "" for cell in row):
                records.append(row)
    except csv.Error:
        pass

    if records and records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    expected_width = 9
    header_index = _find_header(records, expected_width)

    if header_index < 0:
        columns = ["column_" + str(index + 1) for index in range(expected_width)]
        return {"columns": columns, "rows": []}

    header = _normalize_header(records[header_index], expected_width)
    data_records = records[header_index + 1:]

    rows: List[List[str]] = []
    for index, record in enumerate(data_records):
        if not record:
            continue
        if index == len(data_records) - 1 and _looks_like_footer(record):
            continue
        rows.append(_normalize_row(record, expected_width, header))

    return {"columns": header, "rows": rows}
